from pathlib import Path
import json,csv,html,collections,re,datetime
P=Path(__file__).resolve().parent/'taxonomy_reference_build/2026-11-10';A=P/'analysis';L=P/'reference_library'
def js(p):return json.loads(p.read_text(encoding='utf-8'))
def esc(x):return html.escape(str(x))
def table(rows,cols):return '<div class="table"><table><thead><tr>'+''.join('<th>'+esc(label)+'</th>' for key,label in cols)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(d.get(key,''))+'</td>' for key,label in cols)+'</tr>' for d in rows)+'</tbody></table></div>'
def link(p,t):return '<a href="'+p+'">'+t+'</a>'
calls=js(A/'genomic_markers/locus_calls.json');core=[d for d in calls if d['in_core_tree']];sources=js(A/'genome_sources.json');assets=js(A/'assembly_variant_inventory.json');groups=js(A/'assembly_sequence_groups.json');refs=js(A/'tree_reference_metadata.json');accepted=[d for d in js(L/'accepted_species.json') if d['SECTION']=='Terrei'];align=js(A/'tree_inputs/alignment_summary.json');tax=js(A/'sample_taxonomic_review.json');stat=collections.Counter(d['interpretation'] for d in tax);variant=js(A/'assembly_marker_version_comparison.json') if (A/'assembly_marker_version_comparison.json').exists() else []
strict=[d for d in tax if d['interpretation']=='three_locus_supported_concordance'];flags=[d for d in calls if d['status']!='single_strong_candidate'];changes=js(L/'reference_corrections.json');published=js(L/'marker_publications_enriched.json');old=js(A/'orthology_crosscheck/actual_old_BenA_alignment_mapping.json');members=js(A/'orthology_crosscheck/all_relevant_orthogroup_members.json');mapped=js(A/'orthology_crosscheck/validated_marker_gene_mapping.json');tref={d['accepted_type_name']:d for d in refs if d.get('accepted_type_name')}
coverage=[]
for d in accepted:
    r=tref[d['ID'].replace(' ','_')];coverage.append({'nominal_name':d['ID'],'sequence_table_name':r['analysis_species'].replace('_',' '),'strain':r['strain'],'BenA':r['BenAGB'],'CaM':r['CaMGB'],'RPB2':r['RPB2GB'] if r['RPB2_analysis_sequence'] else 'not available','note':'name conflict retained' if r['accepted_type_name']!=r['analysis_species'] else ''})
warnings=[]
for stem in ['combined_all_strains','BenA','CaM','RPB2','type_focused_sensitivity']:
    iq=A/'trees'/(stem+'.iqtree');assert iq.exists(),stem+' incomplete'
    text=iq.read_text();warnings.extend({'analysis':stem,'warning':line.strip()} for line in text.splitlines() if 'WARNING' in line)
    log=A/'logs'/('combined_iqtree.stdout' if stem=='combined_all_strains' else 'type_focused_sensitivity.stdout' if stem=='type_focused_sensitivity' else stem+'_iqtree.stdout')
    for line in log.read_text().splitlines():
        if 'failed composition chi2 test' in line or 'WARNING:' in line:warnings.append({'analysis':stem,'warning':line.strip()})
method='''BLAST+ 2.12.0+ searched assembled genomic DNA locally (blastn, E-value 1e-15, dust=no, minimum hit identity 70%, max_target_seqs=10000). The initial queries were the A. terreus ex-type marker accessions EF669519 (BenA), EF669544 (CaM), and EF669628 (RPB2). Flagged cases were searched against a broader type-reference panel. Hits were grouped by query, contig, strand and proximity (≤2 kb); repeated query spans at separate genomic positions were retained as separate candidate loci. A strong candidate required ≥70% query coverage and ≥85% identity; ≥90% coverage was called near-complete. These are operational screening thresholds, not species boundaries or proof of copy absence. Extracted sequences are homologous barcode windows, not reconstructed full-length CDSs.'''
method2='''MAFFT 7.526 used --localpair --maxiterate 1000 --adjustdirectionaccurately --thread 1 for genomic windows plus curated references. The 2011 sequences were added using --addfragments --keeplength --mapout --thread 1, retaining the reference alignment backbone and recording removed insertions. Columns with A/C/G/T in at least 50% of reference records were retained. Missing loci were encoded as ?; no sample was filled using another strain. Constant sites were retained. IQ-TREE 2.4.0 used DNA models, seed 20261110, one thread, 1,000 UFBoot replicates, 1,000 SH-aLRT replicates and -bnni. The main concatenation used -p partitions.nex -m MFP+MERGE. Model selection merged BenA and CaM into one partition and retained RPB2 separately (TNe+I+G4 for both). Single-locus analyses used -m MFP. Trees were rooted on A. flavipes NRRL302. Branch support is reported as SH-aLRT/UFBoot; the conservative review threshold is ≥80/≥95.'''
gates=[
{'step':'Reference collection','status':'Completed, with provenance flags','gate':'254 curated reference records archived: 173 Terrei, 63 Flavipedes, 18 additional A. candidus/A. fumigatus records. All 81 accessions explicitly listed by the 2011 paper were downloaded. Primary tree: 177 curated records plus 30 historical strain labels. The 29 nominal Terrei names in the accepted table are represented; two names conflict with sequence-table labels.'},
{'step':'Correct marker recovery','status':'Completed for all 66 core-tree labels','gate':'198/198 core-tree marker screens yielded one usable candidate. IFO6365 BenA is partial. Across all 77 assembly labels: BenA 76, CaM 75, RPB2 75 usable windows. HNGD-TM15 has BenA only; SRR33623979 is held from the trees.'},
{'step':'Assembly coverage','status':'Completed for inventoried assembly outputs','gate':f'{len(assets)} assembly files inventoried; {sum(d["bytes"]==0 for d in assets)} empty files flagged. Case/order/header-normalized sequence hashes identify {len(groups)} distinct assembly sequence sets; all were searched. Alternative assembly versions are QC evidence and are not added as independent tree isolates. Inventoried locations: data/assemblies, data/reference and assembly/annotation output paths in results, results1 and results2; training/repeat/protein/transcript intermediates are excluded.'},
{'step':'Copy-number interpretation','status':'Screen completed; biological absence not certified','gate':'No screen produced multiple strong candidates for the same barcode locus. Short secondary tubulin-like hits were retained. Collapsed duplications, divergent paralogs, hard masking and fragmented copies still require read-depth, synteny and protein/gene-tree evidence if a biological duplication claim is made.'},
{'step':'Orthogroup and annotation audit','status':'Repair required before gene-count interpretation','gate':'All 41 actual legacy BenA alignment sequences map to OG0009417. The published BenA window maps to OG0000286 in 63 core samples and fusion-associated OG0002455 in three. CaM has no matching annotated gene model in 20 core samples despite genomic recovery; RPB2 maps to OG0003828 in all 66. Orthogroup membership counts include gene-model fragmentation/fusion effects.'},
{'step':'Reference phylogenies','status':'Completed; exploratory taxonomy draft','gate':'Full 283-tip combined tree, three supported single-locus trees, and a 108-tip type-focused sensitivity tree. The sensitivity tree excludes HNGD-TM15 and A. neoniveus, uses the same sites and fixed selected models, and retains three other Flavipedes outgroups. Some near-zero branches and species boundaries remain unresolved.'},
{'step':'Taxonomic release','status':'Review required','gate':f'{len(strict)} assembly labels meet the deliberately strict three-locus supported single-type-species-clade rule. Other labels are not automatically renamed; insufficient resolution is distinct from conflicting gene histories. All results are marker placements, not a new whole-genome species tree.'},
{'step':'Identity and taxonomy provenance','status':'Review required','gate':'Resolve identical assemblies under different labels and culture aliases before counting independent isolates. Preserve the accepted-list/sequence-table conflicts for A. sofiae and A. mahabadensis, and the published synonymy concerns around A. stefaniae. Missing RPB2 for the A. jilinensis and A. ralucae type records remains missing.'},
{'step':'Resource protection','status':'Enforced for final Linux BLAST/MAFFT/IQ-TREE runs','gate':'Separate cgroup: 2 GiB hard RAM cap, 1 GiB memory.high, zero swap, one CPU quota, Nice=15, IOWeight=10; additional per-process virtual-address limit 1.5 GiB. Panaroo, its files, process and 100 GB cap were not modified.'}]
case_names=['AT2022','IFO6365','IFO6365_DRR204676','TN-484','TN-484_DRR191518','SRR25636141','SRR25636143','NIH2624','HNGD-TM15','SRR33623979']
cases=[d for d in tax if d['sample'] in case_names]
summary={'assembly_labels':len(sources),'assembly_files':len(assets),'unique_assembly_sequence_sets':len(groups),'core_labels':66,'core_usable_locus_calls':sum(bool(d.get('sequence')) for d in core),'library_curated_records':254,'tree_reference_records':len(refs),'combined_tree_tips':283,'type_focused_sensitivity_tips':108,'alignment_sites':sum(d['retained_columns'] for d in align),'actual_legacy_BenA_OG_counts':dict(collections.Counter(','.join(d['orthogroups']) for d in old)),'taxonomy_review_counts':dict(stat),'variant_comparison_counts':dict(collections.Counter(d['comparison'] for d in variant)),'gates':gates}
(P/'status_summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
css='''body{font:16px/1.55 system-ui,Segoe UI,sans-serif;color:#253649;background:#f5f7fa;margin:0}main{max-width:1200px;margin:auto;padding:44px 35px;background:white}h1,h2,h3{color:#203c5c;line-height:1.2}h1{font-size:36px}h2{margin-top:48px;border-top:1px solid #dce4eb;padding-top:25px}.lead{font-size:19px}.note{padding:18px 22px;background:#edf5f4;border-left:5px solid #318a82}.warn{background:#fff5df;border-left-color:#d6a047}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.metric{padding:18px;background:#f0f4f7}.metric strong{display:block;font-size:29px;color:#203c5c}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border-bottom:1px solid #dce4eb;text-align:left;padding:9px;vertical-align:top}th{background:#edf2f7;position:sticky;top:0}a{color:#167970}code{background:#eef2f5;padding:2px 4px}img{max-width:100%;height:auto}.thumb{max-height:720px;display:block;margin:auto}.small{font-size:13px;color:#5e6e7e}li{margin-bottom:7px}details{margin:18px 0}pre{white-space:pre-wrap;background:#f0f4f7;padding:16px}'''
body=f'''<!doctype html><html lang="en"><meta charset="utf-8"><title>Terrei reference loci and taxonomic review — 2026-11-10</title><style>{css}</style><main>
<h1>Terrei reference loci and taxonomic review</h1><p class="lead">Reference-grounded BenA, CaM and RPB2 extraction, assembly cross-checks and draft phylogenies. Source project files were reviewed without modification.</p>
<div class="grid"><div class="metric"><strong>66 / 66</strong>Core-tree labels with all three usable marker windows</div><div class="metric"><strong>155</strong>Distinct assembly sequence sets screened</div><div class="metric"><strong>2,076 sites</strong>515 BenA + 547 CaM + 1,014 RPB2</div></div>
<h2>The old BenA extraction selected another tubulin group</h2><div class="note warn"><b>All 41 sequences actually used in BENA56_aligned.fa belong to OG0009417.</b> In NIH2624, this locus matches the published BenA barcode only over 146 bases at approximately 77% identity. The correct reference-matching genomic region is elsewhere. This supersedes the legacy BenA selection for a phylogeny combined with published BenA sequences.</div>
{table([{'field':'Local gene model','old':'FUN2_006376','new':'FUN2_000298'},{'field':'Orthogroup','old':'OG0009417','new':'OG0000286'},{'field':'NCBI locus','old':'ATEG_06231','new':'ATEG_00287'},{'field':'NCBI product','old':'tubulin beta-1 chain','new':'tubulin beta chain'},{'field':'Marker evidence','old':'146 bp, 76.7% identity to EF669519 in NIH2624','new':'515 bp, 99.8% identity to EF669519 in NIH2624'}],[('field','NIH2624 example'),('old','Previously used'),('new','Published BenA barcode locus')])}
<p>The old annotation carried <code>Name=BENA56</code> and UniProt cross-reference <a href="https://www.uniprot.org/uniprotkb/Q2U2U3/entry">Q2U2U3</a> (A. oryzae, gene benA56). The reference-matching local gene model was labelled “hypothetical protein” and contains both tubulin and RNA-recognition-motif domain annotations, consistent with a problematic merged model. The exact old locus is established; a formal TubC synonym has <b>not</b> been assigned.</p>
<p>The raw legacy FASTA also contains an AT2022 sequence from OG0000286, but that record was not included in the 41-sequence aligned dataset. Raw-file membership and actual tree-input membership are recorded separately.</p>
<p>{link('analysis/marker_gene_crosscheck.tsv','Download the gene-by-gene cross-check')} · {link('analysis/orthology_crosscheck/all_relevant_orthogroup_members.tsv','411 orthogroup member annotations')} · {link('analysis/orthology_crosscheck/actual_old_BenA_alignment_mapping.json','Exact legacy alignment trace')}</p>
<a href="figures/orthogroups_vs_genomic_loci.svg"><img class="thumb" src="figures/orthogroups_vs_genomic_loci.png" alt="Orthogroup member counts and genomic loci"></a>
<h2>Global status and release gates</h2>{table(gates,[('step','Analysis'),('status','Status'),('gate','Evidence and remaining gate')])}
<p>Across 522 assembly-label/version/locus comparisons, 507 validated windows are identical, four differ only by compatible terminal-window coverage, and 11 remain unresolved because usable sequence is unavailable. No validated comparison shows a nucleotide disagreement. These counts include repeated labels and assembly versions, not independent isolates.</p>
<h2>Reference trees and graphics</h2><p>The circular view emphasizes type references and the project assembly labels. Full rectangular phylograms retain all reference and historical strain records. Branch dots require both SH-aLRT ≥80 and UFBoot ≥95; unsupported bifurcations and near-zero branches are not evidence of resolved strain relationships.</p>
<a href="figures/combined_type_focused_circular.svg"><img src="figures/combined_type_focused_circular.png" alt="Type-focused circular reference tree"></a>
<ul><li>{link('figures/combined_type_focused_circular.svg','Circular tree (editable SVG)')} · {link('figures/combined_type_focused_circular.pdf','PDF')}</li>
<li>{link('figures/combined_all_strains_reference_phylogram.svg','Full combined tree (283 tips)')} · {link('analysis/trees/combined_all_strains.treefile','Supported Newick')}</li>
<li>{link('figures/BenA_reference_phylogram.svg','BenA tree')} · {link('figures/CaM_reference_phylogram.svg','CaM tree')} · {link('figures/RPB2_reference_phylogram.svg','RPB2 tree')}</li>
<li>{link('analysis/trees/type_focused_sensitivity.treefile','108-tip sensitivity tree')} · {link('analysis/tree_inputs/type_sensitivity_design.json','Sensitivity design')}</li>
<li>{link('figures/assembly_marker_recovery.svg','All assembly labels: marker recovery')} · {link('analysis/assembly_marker_version_comparison.tsv','Assembly-version comparison')}</li></ul>
<h2>Taxonomic interpretation</h2><p><b>Recovering the correct loci does not resolve every species boundary.</b> IFO6365, TN-484 and AT2022 group with the A. pseudoterreus type with strong support in all three gene trees. SRR25636141 and SRR25636143 group with A. neoindicus in the combined tree and RPB2 tree, warranting review of their previous pseudoterreus labels; the other individual genes do not independently meet the strict clade-support rule. Portions of the terreus–montoensis–neoterreus group remain unresolved. A nearest-type identity score alone is not a species assignment.</p>
<p>HNGD-TM15 has only BenA evidence, placing it near A. floccosus in this screen. SRR33623979 has divergent hits and is excluded from the trees pending a broader taxonomic assessment. No source labels have been overwritten.</p>
<p>Comparing the full and type-focused analyses, 33 project labels retain the same supported type clade; 44 differ in support, resolution or availability. There are no conflicting strongly supported single-species assignments between these analyses. This does not establish species identity for labels lacking independent locus support.</p>
{table(cases,[('sample','Assembly label'),('combined_all_strains_type_species','Supported combined type clade'),('combined_all_strains_SH_aLRT','SH-aLRT'),('combined_all_strains_UFBoot','UFBoot'),('supported_single_species_loci','Independently supported single-species loci'),('interpretation','Review status')])}
<p>{link('analysis/sample_taxonomic_review.tsv','All 77 labels: taxonomic review')} · {link('analysis/nearest_type_reference_matches.tsv','Nearest-type identities and shared bases')} · {link('analysis/supported_type_clades.json','Exact support evidence')}</p>
<h2>Reference coverage and sequence corrections</h2><p>The reference collection is pinned to the <a href="https://doi.org/10.5281/zenodo.23085829">ICPA release of 1 October 2026</a>, supplementing the <a href="https://doi.org/10.3114/sim.2024.107.01">2024 review</a> with subsequent records. The complete downloaded workbook preserves the wider reference database. The analysis includes 173 curated Terrei strain records, four selected Flavipedes ex-types, and 30 historical 2011 strain labels. Historical labels are alternative sequence records, not necessarily independent biological isolates.</p>
<p>All 711 standard nucleotide accessions in the curated subset were retrieved from GenBank. The 27 assembly-derived marker entries are preserved as curated sequences with assembly-accession provenance, not falsely treated as nucleotide accessions. The 2011 accession ranges yielded 29 BenA, 25 CaM and 27 ITS sequences; all 54 BenA/CaM records are included in the tree inputs, while ITS is archived for optional additional analysis.</p>
<p>The original 2024 Figshare alignment deposit could not be retrieved through its repository API; the alignments here were newly reconstructed from the documented sequences. The 2023 supplementary ZIP request returned an HTML challenge, although its article XML, curated strain records and GenBank sequences were retrieved. These retrieval gaps are recorded in <code>source_retrieval_gaps.json</code>.</p>
<div class="note">For BRIP71536a (historically A. marneyi), the accession labels are reversed in the source table: <b>BenA = OL741656; RPB2 = OL741659</b>. Each curated sequence exactly matches the corrected GenBank accession, whose annotated gene agrees. Other unsupported curated/GenBank bases were conservatively masked as N in analysis copies, with exact positions recorded. Source downloads remain intact.</div>
<p>{link('reference_library/reference_corrections.json','Corrections and masked positions')} · {link('reference_library/genbank_reconciliation.json','Sequence verification')} · {link('reference_library/tree_reference_metadata.tsv','Tree reference metadata')} · {link('reference_library/marker_associated_publications.tsv','30 associated citation entries')} · {link('reference_library/marker_publications.ris','RIS library for nine PubMed-linked publications')}</p>
<details><summary>All 29 nominal Terrei type-name entries and locus accessions</summary>{table(coverage,[('nominal_name','Accepted-list name'),('sequence_table_name','Sequence-table label'),('strain','Strain'),('BenA','BenA'),('CaM','CaM'),('RPB2','RPB2'),('note','Flag')])}</details>
<p>A. sofiae is labelled A. alabamensis in the sequence table; the <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC12786731/">2025 update</a> suggests this synonymy and also flags a possible A. stefaniae/A. aureoterreus synonymy. A. mahabadensis is listed separately in the accepted table but its IRAN4983C sequences are labelled A. allahabadii. Both source labels are retained; the package does not silently settle these taxonomic questions.</p>
<h2>Methods, limitations and reproducibility</h2><p>{method}</p><p>{method2}</p>
<p>The current orthogroup matrix was generated by OrthoFinder 3.0.1b1 with <code>-d -t 6</code> on the 66 transcript FASTAs (Results_Sep28). DNA input was explicitly declared. This audit reuses that matrix and checks selected member models and genomic coordinates; it does not rerun OrthoFinder or certify all other orthogroups.</p>
<p>The barcode screen cannot prove that an assembly has no collapsed duplicate or that an undetected locus is biologically absent. No raw-read remapping or annotation repair was performed. Closely related taxa may need additional loci, curated full-length orthologs, broader sampling or genome-level type references. The 2011 dataset contains strain aliases and the project contains identical assemblies under different labels, so tip counts are not counts of independent isolates.</p>
<details><summary>IQ-TREE diagnostics retained for review</summary>{table(warnings,[('analysis','Analysis'),('warning','Diagnostic')])}</details>
<p>Partitioned analyses warn about saturated pairwise distances. Every distance ≥1 involves at least one tip with incomplete locus coverage; none joins two tips with all three loci. The maximum estimate of 9 should not be interpreted as measured biological divergence, and these <code>.mldist</code> files should not be used for heatmap clustering. The type-focused analysis has no composition-test failures, but retains the incomplete-data distance warning. See {link('analysis/pairwise_distance_diagnostics.json','pairwise-distance diagnostic evidence')}.</p>
<p>{link('analysis/identical_assembly_label_groups.tsv','Identical assemblies under multiple labels')} · {link('analysis/assembly_asset_inventory.tsv','Complete assembly-file inventory')} · {link('analysis/tree_inputs/retained_column_map.json','Alignment trimming coordinates')} · {link('download_manifest.json','Downloaded-source URLs and hashes')} · {link('resource_policy.json','Resource limits')} · {link('status_summary.json','Machine-readable status')}</p>
<h2>Files to use</h2><ul><li>New genomic marker FASTAs: <code>analysis/genomic_markers/BenA_genomic.fasta</code>, <code>CaM_genomic.fasta</code>, <code>RPB2_genomic.fasta</code>.</li><li>Final alignments and partitions: <code>analysis/tree_inputs/</code>. Reference metadata: <code>reference_library/tree_reference_metadata.tsv</code>.</li><li>Supported trees, models and bootstrap replicates: <code>analysis/trees/</code>. Figure exports: <code>figures/</code>.</li><li>Legacy diagnostic alignments outside <code>tree_inputs/</code> are retained for audit and are not the corrected tree inputs.</li><li>Exact scripts and execution settings are retained in the workspace and copied into <code>provenance/scripts/</code> as source snapshots. The snapshots retain the original workspace paths.</li></ul>
<p class="small">Analysis dated 10 November 2026. All newly generated files are in this new workspace package. D:\\Illumina\\David_Eisele\\terreus_genotyping was not modified.</p></main></html>'''
(P/'terreus_reference_review.html').write_text(body,encoding='utf-8');print('REPORT',P/'terreus_reference_review.html')
